import { SourceLink } from "@/components/app-link";
import Link from "@/components/app-link";
import { SyncedMediaPlayer } from "@/components/clas-curriculum/media-player";
import { KeyPointsPanel } from "@/components/clas-curriculum/key-points";
import { ChoiceQuestion, OrderingQuestion } from "@/components/clas-curriculum/practice";
import { JobAidActions } from "@/components/clas-curriculum/job-aid-actions";
import type { JobAid, PracticeModule, RecallQuestion } from "@/lib/content/clas-curriculum-practice";
import type { WaterCompanion, WaterImage, WaterLesson } from "@/lib/content/water-curriculum";
import { loadCaptionCues } from "@/lib/content/clas-curriculum-page-data";
import "@/components/clas-curriculum.css";
import "./water-curriculum.css";
import { FeaturedMediaPanel, mediaLength } from "./featured-media-panel";

/** A full-width 4K photograph. The browser picks a smaller rendering for small screens. */
export function WaterFigure({ image, priority = false }: { image: WaterImage; priority?: boolean }) {
  return <figure className={image.slot === "hero" ? "water-figure water-figure-hero" : "water-figure"}>
    {/* eslint-disable-next-line @next/next/no-img-element -- static 4K WebP served as is, sized by CSS */}
    <img src={image.src} alt={image.alt} width={image.width} height={image.height} loading={priority ? "eager" : "lazy"} decoding="async" />
  </figure>;
}

export const heroOf = (lesson: WaterLesson | null) => lesson?.images.find(img => img.slot === "hero") ?? null;

/** Images placed at the start of a module section, keyed by the section heading. */
export function chapterImages(lesson: WaterLesson | null): Record<string, WaterImage> {
  return Object.fromEntries((lesson?.images ?? []).filter(img => img.slot === "chapter" && img.chapter).map(img => [img.chapter!, img]));
}

/**
 * The module podcast, placed directly under the module title and goal so it is found without
 * scrolling. Renders nothing until the release step marks the podcast ready.
 */
export function WaterLessonPodcast({ lesson, moduleTitle, readingHref }: {
  lesson: WaterLesson | null;
  moduleTitle: string;
  readingHref?: string;
}) {
  const podcast = lesson?.podcast;
  if (!podcast) return null;
  const cues = loadCaptionCues(podcast.captions);
  const titleId = `water-podcast-title-${lesson!.id}`;
  const Heading = readingHref ? "h3" : "h2";
  return <div className="water-lesson-opening clas-study">
    <FeaturedMediaPanel kind="podcast" length={mediaLength(podcast.durationSeconds)}><section aria-labelledby={titleId} className="water-podcast">
      <Heading id={titleId}>Listen: {podcast.title}</Heading>
      <p>{podcast.summary} About {Math.max(1, Math.round(podcast.durationSeconds / 60))} minutes. {readingHref
        ? <Link href={readingHref}>Read the original module and its sources</Link>
        : "Two colleagues talk the module through; the full text and its sources follow below."}</p>
      <SyncedMediaPlayer mediaId={`water:${lesson!.id}`} kind="audio" src={podcast.src} captions={podcast.captions} label={`${moduleTitle} podcast`}
        chapters={podcast.chapters} cues={cues} transcriptTitle="Podcast transcript">
        <p className="water-podcast-links"><SourceLink href={podcast.src} download>Download the podcast (MP3)</SourceLink> · <SourceLink href={podcast.transcript}>Read the transcript</SourceLink></p>
      </SyncedMediaPlayer>
    </section></FeaturedMediaPanel>
  </div>;
}

/** After the podcast, before the module text: what this module leads to, a recall from the last one, and the key points. */
export function WaterLessonOpening({ practice, recall, previousTitle, previousNumber }: {
  practice: PracticeModule | null; recall: RecallQuestion[];
  previousTitle?: string; previousNumber?: number;
}) {
  return <div className="water-lesson-opening clas-study">
    {practice?.outcome && <p className="water-outcome"><strong>What you will be able to do: </strong>{practice.outcome.replace(/^After this module you can\s*/i, "")}</p>}
    {previousTitle && previousNumber && recall.length > 0 && <section aria-labelledby="water-recall-title">
      <h2 id="water-recall-title">Before you start: a quick recall from module {previousNumber}</h2>
      <p>Two short questions from “{previousTitle}”. Answer from memory; the feedback explains the reasoning. Nothing is scored or recorded.</p>
      {recall.map(q => <ChoiceQuestion key={q.id} id={`recall-${q.id}`} question={q.question} options={q.options} />)}
    </section>}
    {practice?.keyPoints.length ? <KeyPointsPanel keyPoints={practice.keyPoints} chapters={[]} title="Key points from this module" headingLevel={2} /> : null}
  </div>;
}

function jobAidText(aid: JobAid, title: string): string {
  const lines = [aid.title, `The Water We Swim In: ${title}`, "", aid.useWhen ? `Use when: ${aid.useWhen}` : ""];
  for (const s of aid.sections) lines.push("", s.heading, ...s.items.map(i => `- ${i}`));
  if (aid.remember.length) lines.push("", "Remember", ...aid.remember.map(i => `- ${i}`));
  if (aid.askWho.length) lines.push("", "Who to ask", ...aid.askWho.map(i => `- ${i}`));
  return lines.filter((l, i) => l || i > 3).join("\n") + "\n";
}

/** After the module text: decisions, an ordering exercise and a printable one-page job aid. */
export function WaterLessonPractice({ practice, moduleTitle, moduleNumber }: { practice: PracticeModule | null; moduleTitle: string; moduleNumber: number }) {
  if (!practice) return null;
  const aid = practice.jobAid;
  return <section aria-labelledby="water-practice-title" className="water-practice clas-study">
    <h2 id="water-practice-title">Practice what this module covers</h2>
    {practice.decisions.length > 0 && <div className="clas-decisions">
      <h3>Decisions to practice</h3>
      <p>Each situation is made up and about your next decision. Check an answer to read why it is stronger or weaker; you can try again as often as you like.</p>
      {practice.decisions.map(d => <ChoiceQuestion key={d.id} id={`decision-${d.id}`} question={d.question} scenario={d.scenario} options={d.options} />)}
    </div>}
    {practice.ordering && <OrderingQuestion ordering={practice.ordering} />}
    {aid && <details className="water-job-aid">
      <summary>One-page job aid: {aid.title}</summary>
      <article className="clas-job-aid" aria-labelledby={`water-job-aid-${moduleNumber}`}>
        <p className="clas-study-eyebrow">ONE-PAGE JOB AID · MODULE {moduleNumber}: {moduleTitle.toUpperCase()}</p>
        <h3 id={`water-job-aid-${moduleNumber}`}>{aid.title}</h3>
        {aid.useWhen && <p className="clas-job-aid-use"><strong>Use when:</strong> {aid.useWhen}</p>}
        <div className="clas-job-aid-grid">{aid.sections.map(s => <section key={s.heading}><h4>{s.heading}</h4><ul>{s.items.map(i => <li key={i}>{i}</li>)}</ul></section>)}</div>
        {aid.remember.length > 0 && <section><h4>Remember</h4><ul>{aid.remember.map(i => <li key={i}>{i}</li>)}</ul></section>}
        {aid.askWho.length > 0 && <section><h4>Who to ask</h4><ul>{aid.askWho.map(i => <li key={i}>{i}</li>)}</ul></section>}
        <p className="clas-job-aid-foot">Leave names, case details and other private information out of your notes.</p>
      </article>
      <JobAidActions fileName={`water-we-swim-in-module-${moduleNumber}-job-aid.txt`} text={jobAidText(aid, moduleTitle)} />
    </details>}
    <p className="water-practice-note">Nothing here is scored or recorded. <Link href="#top">Back to the top of the module</Link></p>
  </section>;
}

/**
 * The companion podcast at the top of the course page: one 12 to 15 minute conversation that follows a single
 * planning meeting through all six modules, in the program's two podcast voices, with its photograph.
 * Renders nothing until the release step has verified the recording.
 */
export function WaterCompanionPodcast({ companion }: { companion: WaterCompanion | null }) {
  const podcast = companion?.podcast;
  if (!companion || !podcast) return null;
  const cues = loadCaptionCues(podcast.captions);
  const photo = companion.images.find(img => img.slot === "hero");
  return <div className="water-lesson-opening clas-study water-companion">
    {photo && <WaterFigure image={photo} priority />}
    <FeaturedMediaPanel kind="podcast" length={mediaLength(podcast.durationSeconds)}><section aria-labelledby="water-companion-title" className="water-podcast">
      <h2 id="water-companion-title">Listen first: the whole course in one conversation</h2>
      <p>{podcast.summary} About {Math.max(1, Math.round(podcast.durationSeconds / 60))} minutes, in chapters for each module.</p>
      <SyncedMediaPlayer mediaId="water:companion" kind="audio" src={podcast.src} captions={podcast.captions} label={podcast.title}
        chapters={podcast.chapters} cues={cues} transcriptTitle="Podcast transcript">
        <p className="water-podcast-links"><SourceLink href={podcast.src} download>Download the podcast (MP3)</SourceLink> · <SourceLink href={podcast.transcript}>Read the transcript</SourceLink></p>
      </SyncedMediaPlayer>
    </section></FeaturedMediaPanel>
  </div>;
}

/** How the six modules build on each other: three stages, two modules each. A drawn graphic, no icons. */
const WATER_STAGES = [
  { stage: "See it", modules: [[1, "Notice that the way we do things here is a culture"], [2, "Decode Minnesota nice: warmth, indirectness, the newcomer freeze"]] },
  { stage: "Understand it", modules: [[3, "Trace where it comes from"], [4, "Hear how it feels to Minnesotans of other cultures"]] },
  { stage: "Act on it", modules: [[5, "Find it in disability policy and practice"], [6, "Choose practices that work across difference"]] },
] as const;
export function WaterCoursePath({ hrefFor }: { hrefFor: (number: number) => string }) {
  return <section className="water-path" aria-labelledby="water-path-title">
    <h2 id="water-path-title">How the six modules fit together</h2>
    <ol className="water-path-stages">{WATER_STAGES.map((s, i) => <li key={s.stage} className={`water-path-stage water-path-stage-${i + 1}`}>
      <p className="water-path-stage-name"><span>{i + 1}</span>{s.stage}</p>
      <ol className="water-path-modules">{s.modules.map(([n, text]) => <li key={n} value={n}>
        <SourceLink href={hrefFor(n)}><span className="water-path-number">Module {n}</span><span className="water-path-text">{text}</span></SourceLink>
      </li>)}</ol>
    </li>)}</ol>
  </section>;
}

'use client';
import { useState } from 'react';
import { checkOrdering, type Decision, type Ordering, type PracticeOption, type RecallQuestion } from '@/lib/content/clas-curriculum-practice';

type ChoiceProps = { id: string; question: string; scenario?: string; options: PracticeOption[] };

/**
 * One multiple-choice item: radio buttons, a check button, feedback for the chosen option and a
 * retry. Nothing is recorded; the choice lives only in component state.
 */
export function ChoiceQuestion({ id, question, scenario, options }: ChoiceProps) {
  const [selected, setSelected] = useState<number | null>(null);
  const [checked, setChecked] = useState(false);
  const [needsChoice, setNeedsChoice] = useState(false);
  const chosen = checked && selected !== null ? options[selected] : null;
  return (
    <fieldset className="clas-question">
      <legend>{question}</legend>
      {scenario && <p className="clas-question-scenario">{scenario}</p>}
      {options.map((option, n) => (
        <label key={n}>
          <input type="radio" name={id} value={n} checked={selected === n} onChange={() => { setSelected(n); setChecked(false); setNeedsChoice(false); }} />
          <span>{option.text}</span>
        </label>
      ))}
      <div className="clas-question-actions">
        {!checked
          ? <button type="button" onClick={() => { if (selected === null) setNeedsChoice(true); else setChecked(true); }}>Check my answer</button>
          : <button type="button" className="clas-study-secondary" onClick={() => { setChecked(false); setSelected(null); }}>Try again</button>}
      </div>
      <div className="clas-study-feedback" aria-live="polite">
        {needsChoice && !checked && <p>Choose one option, then check your answer.</p>}
        {chosen && <>
          <h3>{chosen.correct ? 'That is the stronger choice' : 'Not the strongest choice'}</h3>
          <p>{chosen.feedback}</p>
          <p>{chosen.correct ? 'You can choose another response to compare the reasoning.' : 'Try again and compare the reasoning for each option.'}</p>
        </>}
      </div>
    </fieldset>
  );
}

export function RecallSection({ questions, previousTitle, previousPart }: { questions: RecallQuestion[]; previousTitle: string; previousPart: number }) {
  if (!questions.length) return null;
  return (
    <section aria-labelledby="recall">
      <h2 id="recall">Before you watch: a quick recall from Part {previousPart}</h2>
      <p>Two short questions from “{previousTitle}”. Answer from memory; the feedback explains the reasoning. Nothing is scored or recorded.</p>
      {questions.map(q => <ChoiceQuestion key={q.id} id={`recall-${q.id}`} question={q.question} options={q.options} />)}
    </section>
  );
}

export function DecisionList({ decisions }: { decisions: Decision[] }) {
  if (!decisions.length) return null;
  return (
    <div className="clas-decisions">
      <h3>More decisions to practice</h3>
      <p>Each scenario is fictional and about your next decision. Check an answer to read why it is stronger or weaker; you can try again as often as you like.</p>
      {decisions.map(d => <ChoiceQuestion key={d.id} id={`decision-${d.id}`} question={d.question} scenario={d.scenario} options={d.options} />)}
    </div>
  );
}

/**
 * The learner builds an order by choosing the next step from numbered buttons; nothing is dragged.
 * Checking compares each position with the suggested order and allows another attempt.
 */
export function OrderingQuestion({ ordering }: { ordering: Ordering }) {
  const [chosen, setChosen] = useState<number[]>([]);
  const [result, setResult] = useState<ReturnType<typeof checkOrdering> | null>(null);
  const remaining = ordering.steps.map((_, i) => i).filter(i => !chosen.includes(i));
  const complete = chosen.length === ordering.steps.length;
  function reset() { setChosen([]); setResult(null); }
  return (
    <fieldset className="clas-ordering">
      <legend>{ordering.prompt}</legend>
      {ordering.scenario && <p className="clas-question-scenario">{ordering.scenario}</p>}
      <p className="clas-ordering-help">Choose the step you would do first, then the next. Use the numbered buttons; nothing needs to be dragged. You can remove the last step or start over at any time.</p>
      <div className="clas-ordering-chosen">
        <h3>Your order{chosen.length ? ` (${chosen.length} of ${ordering.steps.length})` : ''}</h3>
        {chosen.length
          ? <ol aria-live="polite">{chosen.map((step, position) => <li key={step}>{ordering.steps[step]}{result && <em className={result.matches[position] ? 'clas-order-match' : 'clas-order-miss'}> ({result.matches[position] ? 'in the suggested place' : 'not in the suggested place'})</em>}</li>)}</ol>
          : <p>No steps chosen yet.</p>}
      </div>
      {!complete && (
        <div className="clas-ordering-remaining">
          <h3>Choose step {chosen.length + 1}</h3>
          <ul>{remaining.map(i => <li key={i}><button type="button" className="clas-study-secondary" onClick={() => { setChosen([...chosen, i]); setResult(null); }}>Step {chosen.length + 1}: {ordering.steps[i]}</button></li>)}</ul>
        </div>
      )}
      <div className="clas-question-actions">
        {complete && !result && <button type="button" onClick={() => setResult(checkOrdering(chosen, ordering.correctOrder))}>Check my order</button>}
        {chosen.length > 0 && !result && <button type="button" className="clas-study-secondary" onClick={() => setChosen(chosen.slice(0, -1))}>Remove last step</button>}
        {chosen.length > 0 && <button type="button" className="clas-study-secondary" onClick={reset}>{result ? 'Try again' : 'Start over'}</button>}
      </div>
      <div className="clas-study-feedback" aria-live="polite">
        {result && <>
          <h3>{result.correct ? 'That matches the suggested order' : `Not yet: ${result.matches.filter(Boolean).length} of ${ordering.steps.length} steps are in the suggested place`}</h3>
          {ordering.feedback && <p>{ordering.feedback}</p>}
          {!result.correct && <p>Choose “Try again” to build the order once more.</p>}
        </>}
      </div>
    </fieldset>
  );
}

import type { Metadata } from "next";
import Link from "@/components/app-link";
import { LEADING_LABEL, LEADING_PATHS, REQUIRED_COURSE_LABEL, pathHours } from "@/lib/content/collections";
import base from "@/app/learn/collaboration/collaboration.module.css";
import styles from "@/components/collections.module.css";

export const metadata: Metadata = {
  title: `Suggested paths | ${LEADING_LABEL}`,
  description: "Six optional paths, from exploring leadership to senior leaders. Nobody is enrolled, and progress stays in your browser.",
};

export default function LeadingPathsPage() {
  return <div className={base.page}><div className={base.content}>
    <p className={base.back}><Link href="/leading">{LEADING_LABEL}</Link></p>
    <header className={base.intro}>
      <p className={base.eyebrow}>Optional</p>
      <h1>Suggested paths</h1>
      <p className={base.lede}>Six suggested orders through the material. All of them are optional.</p>
      <p>Not sure where to begin, or how to make a path your own? <Link href="/leading/journey">See how the leadership journey works</Link>.</p>
      <p>Nobody is enrolled, and you can start anywhere or skip anything. If you keep your place, it stays in your browser and nobody else can see it. The one exception to voluntary use is the Equity Analysis Toolkit, marked &ldquo;{REQUIRED_COURSE_LABEL}&rdquo;, which appears on every path for that reason.</p>
    </header>
    <ul className={styles.doors}>
      {LEADING_PATHS.map(path => <li key={path.slug}><Link className={styles.door} href={`/leading/paths/${path.slug}`}>
        <span className={styles.doorTitle}>{path.title}</span>
        <span>{path.description}</span>
        <span className={styles.doorAction}>{path.courseIds.length} courses, about {pathHours(path)} hours</span>
      </Link></li>)}
    </ul>
    <p className={styles.plain}>Times come from each course&apos;s own stated length and have not been tested with readers. They count courses only, not optional practice or live sessions.</p>
  </div></div>;
}

import type { Metadata } from "next";
import Link from "@/components/app-link";
import { notFound } from "next/navigation";
import { LeadingPathPlace, type LeadingPathRow } from "@/components/leading-path-place";
import { LEADING_LABEL, collectionItem, collectionItemHref, leadingPath, pathHours } from "@/lib/content/collections";
import { publishedCourses } from "@/lib/content/courses/published";
import { requestedContentScope } from "@/lib/product/request-context";
import { PATH_JOURNEY } from "@/lib/content/leadership-journey";
import base from "@/app/learn/collaboration/collaboration.module.css";
import styles from "@/components/collections.module.css";

export const dynamic = "force-dynamic";
export async function generateMetadata({ params }: { params: Promise<{ path: string }> }): Promise<Metadata> {
  const path = leadingPath((await params).path);
  return path ? { title: `${path.title}: a suggested path`, description: path.description } : {};
}

export default async function LeadingPathPage({ params }: { params: Promise<{ path: string }> }) {
  const path = leadingPath((await params).path);
  if (!path) notFound();
  const scope = await requestedContentScope();
  const published = new Set((await publishedCourses(scope)).map(({ pack }) => pack.course.id));
  const journey = PATH_JOURNEY[path.slug];
  const rows: LeadingPathRow[] = path.courseIds.map(id => {
    const item = collectionItem(id);
    if (!item) return { id, title: id };
    return { id, title: item.title, minutes: item.minutes, required: item.required, href: item.kind !== "course" || published.has(id) ? collectionItemHref(item) : undefined };
  });
  return <div className={base.page}><div className={base.content}>
    <p className={base.back}><Link href="/leading/paths">Suggested paths</Link></p>
    <header className={base.intro}>
      <p className={base.eyebrow}>{LEADING_LABEL} · optional</p>
      <h1>{path.title}</h1>
      <p className={base.lede}>{path.description}</p>
      <p>{path.courseIds.length} courses, about {pathHours(path)} hours in all, at your own pace. This is a suggestion. Start anywhere and skip anything. Your place stays in this browser, and anyone using this computer could see it. Nothing is sent to a supervisor or employer. <Link href="/leading/how-this-works">How this works</Link>.</p>
    </header>
    {journey ? <section className={styles.section} aria-labelledby="path-question-title">
      <h2 id="path-question-title">The question this path keeps asking</h2>
      <p>{journey.question}</p>
      <h3 className="mt-4">Something to try in your own work</h3>
      <p>{journey.tryThis}</p>
      <p className={styles.plain}>What to keep: {journey.keep} It stays with you; nothing is submitted.</p>
      <p className="mt-3 flex flex-wrap gap-x-6 gap-y-2">
        <Link href={`/my-work/action-plan?from=${encodeURIComponent(path.title + " path")}`}>Start an action plan</Link>
        <Link href={`/my-work/reflections?from=${encodeURIComponent(path.title + " path")}`}>Open your reflection notebook</Link>
        <Link href="/leading/journey">How the journey works</Link>
      </p>
    </section> : null}
    <LeadingPathPlace pathId={path.slug} rows={rows} />
  </div></div>;
}

import Link from "@/components/app-link";
import type { Metadata } from "next";
import { RecordWorkbench } from "@/components/record-workbench";

export const metadata: Metadata = { title: "Decision records" };

export default function DecisionRecordsPage() {
  return <div className="calm calm-narrow">
    <nav className="calm-crumbs" aria-label="Breadcrumb"><Link href="/my-work">My work</Link></nav>
    <p className="calm-kicker">Write down why</p>
    <h1>Decision records</h1>
    <p className="calm-lede">A short, plain record of a consequential decision: who it affects, what was heard, the options weighed and why one was chosen. Someone reading it next year should be able to follow the reasoning.</p>
    <details>
      <summary>When to keep a decision record</summary>
      <p>Keep one for a policy, form, notice, budget, hiring or service change that affects people outside your team. If the Equity Analysis Toolkit applies, the record notes where its analysis is kept. A record supports a decision; the person or area responsible still makes it.</p>
      <p><Link href="/team-space">See records saved to the team space</Link></p>
    </details>
    <RecordWorkbench kind="decision-record" teamSpace />
  </div>;
}

import Link from "@/components/app-link";
import type { Metadata } from "next";
import { RecordWorkbench } from "@/components/record-workbench";
import { REFLECTION_PROMPTS } from "@/lib/content/leadership-journey";

export const metadata: Metadata = { title: "Your reflection notebook" };

type Props = { searchParams: Promise<{ from?: string }> };

export default async function ReflectionsPage({ searchParams }: Props) {
  const { from } = await searchParams;
  const source = typeof from === "string" ? from.slice(0, 200) : "";
  return <div className="calm calm-narrow">
    <nav className="calm-crumbs" aria-label="Breadcrumb"><Link href="/my-work">My work</Link></nav>
    <p className="calm-kicker">Look back and learn</p>
    <h1>Your reflection notebook</h1>
    <p className="calm-lede">A few honest lines after a lesson, a hard moment or a finished piece of work. Three questions carry most of it: what happened, why it matters, and what you will do next.</p>
    <details>
      <summary>Questions for each kind of reflection</summary>
      <ul className="list-disc space-y-2 pl-6">
        {REFLECTION_PROMPTS.map(prompt => <li key={prompt.kind}><strong>{prompt.kind}.</strong> {prompt.when} {prompt.questions.join(" ")}</li>)}
      </ul>
      <p>Set a date to look back. When it arrives, the notebook shows you the reflection the next time you open this page.</p>
    </details>
    <RecordWorkbench kind="reflection" prefill={source ? { about: source, title: `Reflection: ${source}`.slice(0, 160) } : {}} />
    <p className="calm-muted calm-small">Part of <Link href="/leading/journey">your leadership journey</Link>, and open to everyone.</p>
  </div>;
}
